CREATE TABLE payment_order (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, payment_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, channel VARCHAR(32) NOT NULL, currency CHAR(3) NOT NULL, amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, expire_at DATETIME(3) NULL, provider_merchant_ref VARCHAR(128) NULL, idempotency_key VARCHAR(128) NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_payment_no(payment_no), UNIQUE KEY uk_payment_idem(tenant_id,idempotency_key), KEY idx_payment_customer(tenant_id,customer_id,status));
CREATE TABLE payment_business_relation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, payment_order_id BIGINT NOT NULL, business_type VARCHAR(32) NOT NULL, business_id BIGINT NOT NULL, expected_amount DECIMAL(18,2) NOT NULL, KEY idx_pay_biz(tenant_id,business_type,business_id));
CREATE TABLE payment_transaction (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, payment_order_id BIGINT NOT NULL, channel VARCHAR(32) NOT NULL, channel_trade_no VARCHAR(128) NOT NULL, transaction_type VARCHAR(32) NOT NULL, amount DECIMAL(18,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(32) NOT NULL, occurred_at DATETIME(3) NOT NULL, raw_payload_hash VARCHAR(128) NULL, UNIQUE KEY uk_channel_trade(channel,channel_trade_no), KEY idx_pt_order(tenant_id,payment_order_id));
CREATE TABLE payment_callback_log (id BIGINT PRIMARY KEY, tenant_id BIGINT NULL, channel VARCHAR(32) NOT NULL, request_id VARCHAR(128) NULL, merchant_ref VARCHAR(128) NULL, payment_no VARCHAR(64) NULL, body_hash VARCHAR(128) NOT NULL, signature_valid TINYINT NOT NULL, process_result VARCHAR(64) NOT NULL, received_at DATETIME(3) NOT NULL, KEY idx_cb_payment(payment_no,received_at));
CREATE TABLE refund_order (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, refund_no VARCHAR(64) NOT NULL, payment_order_id BIGINT NOT NULL, original_transaction_id BIGINT NOT NULL, refund_amount DECIMAL(18,2) NOT NULL, reason VARCHAR(512) NULL, status VARCHAR(32) NOT NULL, provider_refund_no VARCHAR(128) NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_refund_no(refund_no), KEY idx_refund_payment(tenant_id,payment_order_id,status));
CREATE TABLE refund_transaction (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, refund_order_id BIGINT NOT NULL, provider_refund_no VARCHAR(128) NOT NULL, amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, occurred_at DATETIME(3) NOT NULL, UNIQUE KEY uk_provider_refund(provider_refund_no));
